CREATE TABLE public.companies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,owner_id uuid NOT NULL REFERENCES public.profiles(id),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.companies TO authenticated; GRANT ALL ON public.companies TO service_role;
ALTER TABLE public.companies ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.company_memberships(company_id uuid NOT NULL REFERENCES public.companies(id),user_id uuid NOT NULL REFERENCES public.profiles(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,user_id));
GRANT SELECT ON public.company_memberships TO authenticated; GRANT ALL ON public.company_memberships TO service_role;
ALTER TABLE public.company_memberships ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_company_context(user_id uuid PRIMARY KEY REFERENCES public.profiles(id),company_id uuid NOT NULL REFERENCES public.companies(id),FOREIGN KEY(company_id,user_id) REFERENCES public.company_memberships(company_id,user_id));
GRANT SELECT ON public.user_company_context TO authenticated; GRANT ALL ON public.user_company_context TO service_role;
ALTER TABLE public.user_company_context ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.company_invitations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),email text NOT NULL,token_hash text NOT NULL UNIQUE,invited_by uuid NOT NULL REFERENCES public.profiles(id),expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days',accepted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.company_invitations TO authenticated; GRANT ALL ON public.company_invitations TO service_role;
ALTER TABLE public.company_invitations ENABLE ROW LEVEL SECURITY;
INSERT INTO public.companies(id,name,owner_id) SELECT id,coalesce(nullif(trim(empresa),''),'Minha Empresa'),id FROM public.profiles;
INSERT INTO public.company_memberships(company_id,user_id) SELECT id,owner_id FROM public.companies;
INSERT INTO public.user_company_context(user_id,company_id) SELECT owner_id,id FROM public.companies;
CREATE FUNCTION public.active_company_id() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT company_id FROM public.user_company_context WHERE user_id=auth.uid() $$;
CREATE FUNCTION public.is_company_member(p_company uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.company_memberships WHERE company_id=p_company AND user_id=auth.uid()) $$;
CREATE FUNCTION public.can_manage_company(p_company uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND (public.is_admin_principal(auth.uid()) OR EXISTS(SELECT 1 FROM public.companies WHERE id=p_company AND owner_id=auth.uid())) $$;
CREATE FUNCTION public.can_read_company(p_company uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND (public.is_admin_principal(auth.uid()) OR (p_company=public.active_company_id() AND public.is_company_member(p_company))) $$;
REVOKE ALL ON FUNCTION public.active_company_id(),public.is_company_member(uuid),public.can_manage_company(uuid),public.can_read_company(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.active_company_id(),public.is_company_member(uuid),public.can_manage_company(uuid),public.can_read_company(uuid) TO authenticated,service_role;
CREATE POLICY company_read ON public.companies FOR SELECT TO authenticated USING(public.is_company_member(id) OR public.is_admin_principal(auth.uid()));
CREATE POLICY company_rename ON public.companies FOR UPDATE TO authenticated USING(public.can_manage_company(id)) WITH CHECK(public.can_manage_company(id));
CREATE POLICY membership_read ON public.company_memberships FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.can_manage_company(company_id));
CREATE POLICY context_read ON public.user_company_context FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY invitation_read ON public.company_invitations FOR SELECT TO authenticated USING(public.can_manage_company(company_id));
CREATE FUNCTION public.protect_company_owner() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.id IS DISTINCT FROM OLD.id OR NEW.owner_id IS DISTINCT FROM OLD.owner_id THEN RAISE EXCEPTION 'Proprietário da empresa não pode ser alterado'; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_company_owner BEFORE UPDATE ON public.companies FOR EACH ROW EXECUTE FUNCTION public.protect_company_owner();
CREATE FUNCTION public.bootstrap_company() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.companies(id,name,owner_id) VALUES(NEW.id,coalesce(nullif(trim(NEW.empresa),''),'Minha Empresa'),NEW.id); INSERT INTO public.company_memberships(company_id,user_id) VALUES(NEW.id,NEW.id); INSERT INTO public.user_company_context(user_id,company_id) VALUES(NEW.id,NEW.id); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.bootstrap_company() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER profile_bootstrap_company AFTER INSERT ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.bootstrap_company();
CREATE FUNCTION public.select_company(p_company uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_company_member(p_company) AND NOT public.is_admin_principal(auth.uid()) THEN RAISE EXCEPTION 'Sem acesso a esta empresa'; END IF; IF public.is_admin_principal(auth.uid()) THEN INSERT INTO public.company_memberships(company_id,user_id) VALUES(p_company,auth.uid()) ON CONFLICT DO NOTHING; END IF; UPDATE public.user_company_context SET company_id=p_company WHERE user_id=auth.uid(); END $$;
CREATE FUNCTION public.create_company_invitation(p_email text) RETURNS TABLE(invitation_id uuid,token text,company_name text) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c uuid:=public.active_company_id(); t text; i uuid; BEGIN IF NOT public.can_manage_company(c) THEN RAISE EXCEPTION 'Somente o proprietário da empresa ou administradores podem convidar'; END IF; IF trim(p_email) !~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR length(p_email)>254 THEN RAISE EXCEPTION 'E-mail inválido'; END IF; t:=encode(extensions.gen_random_bytes(32),'hex'); INSERT INTO public.company_invitations(company_id,email,token_hash,invited_by) VALUES(c,lower(trim(p_email)),encode(extensions.digest(t,'sha256'),'hex'),auth.uid()) RETURNING id INTO i; RETURN QUERY SELECT i,t,name FROM public.companies WHERE id=c; END $$;
CREATE FUNCTION public.accept_company_invitation(p_token text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.company_invitations; e text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Entre na sua conta para aceitar o convite'; END IF; SELECT lower(email) INTO e FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL; SELECT * INTO i FROM public.company_invitations WHERE token_hash=encode(extensions.digest(p_token,'sha256'),'hex') FOR UPDATE; IF i.id IS NULL OR i.accepted_at IS NOT NULL OR i.expires_at<=now() OR e IS NULL OR e<>i.email THEN RAISE EXCEPTION 'Convite inválido, expirado ou destinado a outro e-mail'; END IF; INSERT INTO public.company_memberships(company_id,user_id) VALUES(i.company_id,auth.uid()) ON CONFLICT DO NOTHING; UPDATE public.user_company_context SET company_id=i.company_id WHERE user_id=auth.uid(); UPDATE public.company_invitations SET accepted_at=now() WHERE id=i.id; RETURN i.company_id; END $$;
REVOKE ALL ON FUNCTION public.select_company(uuid),public.create_company_invitation(text),public.accept_company_invitation(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.select_company(uuid),public.create_company_invitation(text),public.accept_company_invitation(text) TO authenticated;
DO $$ DECLARE t text; p record; BEGIN FOREACH t IN ARRAY ARRAY['obras','checklists','inspecoes','contractors','employees','company_documents','employee_documents','company_job_roles','listas_presenca','itens_checklist','itens_inspecao','nao_conformidades','acoes_corretivas','respostas_inspecao','pavimentos','lista_presenca_participantes','fotos_inspecao','fotos_item_inspecao','fotos_nao_conformidade','fotos_acao_corretiva','nc_links'] LOOP IF t='listas_presenca' THEN ALTER TABLE public.listas_presenca DROP CONSTRAINT listas_presenca_company_id_fkey; ALTER TABLE public.listas_presenca ADD CONSTRAINT listas_presenca_company_id_fkey FOREIGN KEY(company_id) REFERENCES public.companies(id); ELSE EXECUTE format('ALTER TABLE public.%I ADD COLUMN company_id uuid REFERENCES public.companies(id)',t); END IF; EXECUTE format('UPDATE public.%I SET company_id=user_id WHERE company_id IS NULL',t); EXECUTE format('ALTER TABLE public.%I ALTER COLUMN company_id SET DEFAULT public.active_company_id()',t); EXECUTE format('CREATE INDEX %I ON public.%I(company_id)',t||'_company_idx',t); END LOOP; END $$;
CREATE FUNCTION public.enforce_record_company() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j jsonb:=to_jsonb(NEW); c uuid; parent_c uuid; parent_id uuid; k integer; path text; actor uuid:=auth.uid(); BEGIN c:=NEW.company_id; IF TG_OP='UPDATE' AND (NEW.company_id IS DISTINCT FROM OLD.company_id OR NEW.user_id IS DISTINCT FROM OLD.user_id) THEN RAISE EXCEPTION 'Empresa e autor do registro não podem ser alterados'; END IF; IF TG_OP='INSERT' THEN c:=NULL; END IF; IF TG_NARGS>0 THEN FOR k IN 0..TG_NARGS/2-1 LOOP parent_id:=nullif(j->>TG_ARGV[k*2],'')::uuid; IF parent_id IS NOT NULL THEN EXECUTE format('SELECT company_id FROM public.%I WHERE id=$1',TG_ARGV[k*2+1]) INTO parent_c USING parent_id; IF parent_c IS NULL THEN RAISE EXCEPTION 'Registro relacionado não encontrado'; END IF; IF c IS NULL THEN c:=parent_c; ELSIF c<>parent_c THEN RAISE EXCEPTION 'Registros de empresas diferentes não podem ser vinculados'; END IF; END IF; END LOOP; END IF; IF TG_OP='INSERT' THEN c:=coalesce(c,NEW.company_id,public.active_company_id()); IF NEW.company_id IS NOT NULL AND NEW.company_id<>c AND NEW.company_id<>public.active_company_id() THEN RAISE EXCEPTION 'Empresa informada não corresponde ao registro'; END IF; NEW.company_id:=c; END IF; IF c IS NULL THEN RAISE EXCEPTION 'Selecione uma empresa'; END IF; IF actor IS NOT NULL AND NOT public.can_read_company(c) THEN RAISE EXCEPTION 'Sem acesso a esta empresa'; END IF; IF TG_OP='INSERT' AND actor IS NOT NULL AND NEW.user_id<>actor AND NOT public.is_admin_principal(actor) THEN IF TG_TABLE_NAME<>'lista_presenca_participantes' OR NOT EXISTS(SELECT 1 FROM public.listas_presenca WHERE id=(j->>'lista_id')::uuid AND user_id=actor) THEN RAISE EXCEPTION 'Autor inválido'; END IF; END IF; path:=coalesce(j->>'url',j->>'file_url'); IF path IS NOT NULL AND (TG_OP='INSERT' OR path IS DISTINCT FROM coalesce(to_jsonb(OLD)->>'url',to_jsonb(OLD)->>'file_url')) THEN IF path LIKE 'companies/%' THEN IF split_part(path,'/',2)<>c::text THEN RAISE EXCEPTION 'Arquivo pertence a outra empresa'; END IF; ELSIF split_part(path,'/',1)<>NEW.user_id::text THEN RAISE EXCEPTION 'Arquivo pertence a outro usuário'; END IF; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.enforce_record_company() FROM PUBLIC,anon,authenticated;
DO $$ DECLARE t text; p record; w text; a text; link text[]; links jsonb:='{"inspecoes":["obra_id","obras"],"employees":["contractor_id","contractors"],"company_documents":["contractor_id","contractors"],"employee_documents":["employee_id","employees"],"company_job_roles":["contractor_id","contractors"],"itens_checklist":["checklist_id","checklists"],"itens_inspecao":["inspecao_id","inspecoes"],"nao_conformidades":["inspecao_id","inspecoes","item_inspecao_id","itens_inspecao","obra_id","obras"],"acoes_corretivas":["nao_conformidade_id","nao_conformidades"],"respostas_inspecao":["inspecao_id","inspecoes","item_checklist_id","itens_checklist"],"pavimentos":["obra_id","obras"],"lista_presenca_participantes":["lista_id","listas_presenca","employee_id","employees"],"fotos_inspecao":["inspecao_id","inspecoes"],"fotos_item_inspecao":["item_inspecao_id","itens_inspecao"],"fotos_nao_conformidade":["nao_conformidade_id","nao_conformidades"],"fotos_acao_corretiva":["acao_corretiva_id","acoes_corretivas"],"nc_links":["nao_conformidade_id","nao_conformidades"]}'; BEGIN FOREACH t IN ARRAY ARRAY['obras','checklists','inspecoes','contractors','employees','company_documents','employee_documents','company_job_roles','listas_presenca','itens_checklist','itens_inspecao','nao_conformidades','acoes_corretivas','respostas_inspecao','pavimentos','lista_presenca_participantes','fotos_inspecao','fotos_item_inspecao','fotos_nao_conformidade','fotos_acao_corretiva','nc_links'] LOOP IF links ? t THEN SELECT array_agg(value) INTO link FROM jsonb_array_elements_text(links->t); EXECUTE format('UPDATE public.%I t SET company_id=p.company_id FROM public.%I p WHERE t.%I=p.id',t,link[2],link[1]); SELECT string_agg(quote_literal(value),',') INTO a FROM jsonb_array_elements_text(links->t); ELSE a:=''; END IF; EXECUTE format('CREATE TRIGGER record_company BEFORE INSERT OR UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.enforce_record_company(%s)',t,a); FOR p IN SELECT policyname FROM pg_policies WHERE schemaname='public' AND tablename=t LOOP EXECUTE format('DROP POLICY %I ON public.%I',p.policyname,t); END LOOP; EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('GRANT SELECT,INSERT,UPDATE,DELETE ON public.%I TO authenticated',t); EXECUTE format('GRANT ALL ON public.%I TO service_role',t); EXECUTE format('CREATE POLICY tenant_read ON public.%I FOR SELECT TO authenticated USING(public.can_read_company(company_id))',t); w:='public.can_read_company(company_id) AND (user_id=auth.uid() OR public.is_admin_principal(auth.uid()))'; IF t IN ('checklists','itens_checklist') THEN w:='public.can_read_company(company_id) AND public.is_admin_principal(auth.uid())'; END IF; EXECUTE format('CREATE POLICY tenant_insert ON public.%I FOR INSERT TO authenticated WITH CHECK(%s)',t,w); IF t<>'nc_links' THEN EXECUTE format('CREATE POLICY tenant_update ON public.%I FOR UPDATE TO authenticated USING(%s) WITH CHECK(%s)',t,w,w); END IF; EXECUTE format('CREATE POLICY tenant_delete ON public.%I FOR DELETE TO authenticated USING(%s)',t,w); END LOOP; END $$;
CREATE FUNCTION public.can_access_company_file(p_bucket text,p_path text,p_write boolean DEFAULT false) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE c uuid; u uuid; segment text; BEGIN IF auth.uid() IS NULL OR p_bucket NOT IN ('fotos','documentos') THEN RETURN false; END IF; IF p_path LIKE 'companies/%' THEN c:=split_part(p_path,'/',2)::uuid; u:=split_part(p_path,'/',3)::uuid; ELSE u:=split_part(p_path,'/',1)::uuid; segment:=split_part(p_path,'/',2); IF segment='perfil' THEN RETURN u=auth.uid() OR public.is_admin_principal(auth.uid()); END IF; SELECT company_id INTO c FROM (SELECT company_id FROM public.company_documents WHERE file_url=p_path AND p_bucket='documentos' UNION ALL SELECT company_id FROM public.employee_documents WHERE file_url=p_path AND p_bucket='documentos' UNION ALL SELECT company_id FROM public.fotos_inspecao WHERE url=p_path AND p_bucket='fotos' UNION ALL SELECT company_id FROM public.fotos_item_inspecao WHERE url=p_path AND p_bucket='fotos' UNION ALL SELECT company_id FROM public.fotos_nao_conformidade WHERE url=p_path AND p_bucket='fotos' UNION ALL SELECT company_id FROM public.fotos_acao_corretiva WHERE url=p_path AND p_bucket='fotos') assets LIMIT 1; c:=coalesce(c,u); END IF; RETURN public.can_read_company(c) AND (NOT p_write OR u=auth.uid() OR public.is_admin_principal(auth.uid())); EXCEPTION WHEN invalid_text_representation THEN RETURN false; END $$;
REVOKE ALL ON FUNCTION public.can_access_company_file(text,text,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.can_access_company_file(text,text,boolean) TO authenticated,service_role;
DO $$ DECLARE b text; s text; BEGIN FOREACH b IN ARRAY ARRAY['fotos','documentos'] LOOP FOREACH s IN ARRAY ARRAY['select_own_or_admin','insert_own','insert_own_or_admin','update_own_or_admin','delete_own_or_admin'] LOOP EXECUTE format('DROP POLICY IF EXISTS %I ON storage.objects',b||'_'||s); END LOOP; EXECUTE format('CREATE POLICY %I ON storage.objects FOR SELECT TO authenticated USING(bucket_id=%L AND public.can_access_company_file(bucket_id,name,false))',b||'_tenant_read',b); EXECUTE format('CREATE POLICY %I ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id=%L AND public.can_access_company_file(bucket_id,name,true))',b||'_tenant_insert',b); EXECUTE format('CREATE POLICY %I ON storage.objects FOR UPDATE TO authenticated USING(bucket_id=%L AND public.can_access_company_file(bucket_id,name,true)) WITH CHECK(bucket_id=%L AND public.can_access_company_file(bucket_id,name,true))',b||'_tenant_update',b,b); EXECUTE format('CREATE POLICY %I ON storage.objects FOR DELETE TO authenticated USING(bucket_id=%L AND public.can_access_company_file(bucket_id,name,true))',b||'_tenant_delete',b); END LOOP; END $$;